def transform(grid):
    """Transform colored rectangular regions into a frame pattern: corners=1, edges=4, interior=2."""
    if not grid or not grid[0]:
        return grid

    rows = len(grid)
    cols = len(grid[0])

    # Background color
    background = 3

    output = [[background for _ in range(cols)] for _ in range(rows)]

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == background:
                continue

            color = grid[r][c]

            # Find the bounding box of this region
            min_r, max_r = r, r
            min_c, max_c = c, c

            # Expand in all directions
            for dr in range(-10, 10):
                for dc in range(-10, 10):
                    if 0 <= r + dr < rows and 0 <= c + dc < cols:
                        if grid[r + dr][c + dc] == color:
                            min_r = min(min_r, r + dr)
                            max_r = max(max_r, r + dr)
                            min_c = min(min_c, c + dc)
                            max_c = max(max_c, c + dc)

            # Transform the rectangle
            for rr in range(min_r, max_r + 1):
                for cc in range(min_c, max_c + 1):
                    if grid[rr][cc] == color:
                        # Determine if corner, edge, or interior
                        is_corner = (rr == min_r and cc == min_c) or \
                                   (rr == min_r and cc == max_c) or \
                                   (rr == max_r and cc == min_c) or \
                                   (rr == max_r and cc == max_c)
                        is_edge = (rr == min_r and not is_corner) or \
                                  (rr == max_r and not is_corner) or \
                                  (cc == min_c and not is_corner) or \
                                  (cc == max_c and not is_corner)
                        is_interior = (min_r < rr < max_r) and (min_c < cc < max_c)

                        if is_corner:
                            output[rr][cc] = 1
                        elif is_edge:
                            output[rr][cc] = 4
                        elif is_interior:
                            output[rr][cc] = 2

    return output

